def lcf_graph(n, shifts, repeat):
    edges = set()
    for i in range(n):
        u, v = i, (i+1) % n
        if u > v: u, v = v, u
        edges.add((u, v))
    pattern = shifts * repeat
    for i in range(n):
        shift = pattern[i % len(pattern)]
        j = (i + shift) % n
        u, v = min(i, j), max(i, j)
        edges.add((u, v))
    return list(edges)

